CREATE TABLE en1993_document(id INTEGER PRIMARY KEY CHECK(id=1),annex TEXT NOT NULL CHECK(annex IN ('En','De')));
CREATE TABLE en1993_material(
 id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES en1993_document(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),logical_id TEXT NOT NULL,grade TEXT NOT NULL,fy REAL,fu REAL,e_modulus REAL,g_modulus REAL,subgrade TEXT NOT NULL,kind TEXT NOT NULL,
 fy_ieee754_bits INTEGER NOT NULL,fy_ieee754_class TEXT NOT NULL,fu_ieee754_bits INTEGER NOT NULL,fu_ieee754_class TEXT NOT NULL,e_modulus_ieee754_bits INTEGER NOT NULL,e_modulus_ieee754_class TEXT NOT NULL,g_modulus_ieee754_bits INTEGER NOT NULL,g_modulus_ieee754_class TEXT NOT NULL
);
CREATE TABLE en1993_section(
 id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES en1993_document(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),logical_id TEXT NOT NULL,designation TEXT NOT NULL,kind TEXT NOT NULL,h REAL,b REAL,tw REAL,tf REAL,r REAL,area REAL,shear_area_y REAL,shear_area_z REAL,iy REAL,iz REAL,it REAL,iw REAL,w_el_y REAL,w_el_z REAL,w_pl_y REAL,w_pl_z REAL,area_net REAL,
 h_ieee754_bits INTEGER NOT NULL,h_ieee754_class TEXT NOT NULL,b_ieee754_bits INTEGER NOT NULL,b_ieee754_class TEXT NOT NULL,tw_ieee754_bits INTEGER NOT NULL,tw_ieee754_class TEXT NOT NULL,tf_ieee754_bits INTEGER NOT NULL,tf_ieee754_class TEXT NOT NULL,r_ieee754_bits INTEGER NOT NULL,r_ieee754_class TEXT NOT NULL,area_ieee754_bits INTEGER NOT NULL,area_ieee754_class TEXT NOT NULL,shear_area_y_ieee754_bits INTEGER NOT NULL,shear_area_y_ieee754_class TEXT NOT NULL,shear_area_z_ieee754_bits INTEGER NOT NULL,shear_area_z_ieee754_class TEXT NOT NULL,iy_ieee754_bits INTEGER NOT NULL,iy_ieee754_class TEXT NOT NULL,iz_ieee754_bits INTEGER NOT NULL,iz_ieee754_class TEXT NOT NULL,it_ieee754_bits INTEGER NOT NULL,it_ieee754_class TEXT NOT NULL,iw_ieee754_bits INTEGER NOT NULL,iw_ieee754_class TEXT NOT NULL,w_el_y_ieee754_bits INTEGER NOT NULL,w_el_y_ieee754_class TEXT NOT NULL,w_el_z_ieee754_bits INTEGER NOT NULL,w_el_z_ieee754_class TEXT NOT NULL,w_pl_y_ieee754_bits INTEGER NOT NULL,w_pl_y_ieee754_class TEXT NOT NULL,w_pl_z_ieee754_bits INTEGER NOT NULL,w_pl_z_ieee754_class TEXT NOT NULL,area_net_ieee754_bits INTEGER NOT NULL,area_net_ieee754_class TEXT NOT NULL
);
CREATE TABLE en1993_member(
 id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES en1993_document(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),logical_id TEXT NOT NULL,label TEXT NOT NULL,member_type TEXT NOT NULL,section_id TEXT NOT NULL,material_id TEXT NOT NULL,length REAL,buckling_length_y REAL,buckling_length_z REAL,ltb_length REAL,ltb_restraint_spacing REAL,load_application TEXT NOT NULL,end_moment_ratio_psi REAL,moment_diagram TEXT NOT NULL,deflection_limit_ratio REAL,analysis TEXT NOT NULL,
 length_ieee754_bits INTEGER NOT NULL,length_ieee754_class TEXT NOT NULL,buckling_length_y_ieee754_bits INTEGER NOT NULL,buckling_length_y_ieee754_class TEXT NOT NULL,buckling_length_z_ieee754_bits INTEGER NOT NULL,buckling_length_z_ieee754_class TEXT NOT NULL,ltb_length_ieee754_bits INTEGER NOT NULL,ltb_length_ieee754_class TEXT NOT NULL,ltb_restraint_spacing_ieee754_bits INTEGER NOT NULL,ltb_restraint_spacing_ieee754_class TEXT NOT NULL,end_moment_ratio_psi_ieee754_bits INTEGER NOT NULL,end_moment_ratio_psi_ieee754_class TEXT NOT NULL,deflection_limit_ratio_ieee754_bits INTEGER NOT NULL,deflection_limit_ratio_ieee754_class TEXT NOT NULL
);
CREATE TABLE en1993_load_case(id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES en1993_document(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),logical_id TEXT NOT NULL,name TEXT NOT NULL,kind TEXT NOT NULL,category TEXT NOT NULL);
CREATE TABLE en1993_member_action(
 id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES en1993_document(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),logical_id TEXT NOT NULL,member_id TEXT NOT NULL,load_case_id TEXT NOT NULL,action_n REAL,action_vy REAL,action_vz REAL,action_my REAL,action_mz REAL,action_t REAL,
 action_n_ieee754_bits INTEGER NOT NULL,action_n_ieee754_class TEXT NOT NULL,action_vy_ieee754_bits INTEGER NOT NULL,action_vy_ieee754_class TEXT NOT NULL,action_vz_ieee754_bits INTEGER NOT NULL,action_vz_ieee754_class TEXT NOT NULL,action_my_ieee754_bits INTEGER NOT NULL,action_my_ieee754_class TEXT NOT NULL,action_mz_ieee754_bits INTEGER NOT NULL,action_mz_ieee754_class TEXT NOT NULL,action_t_ieee754_bits INTEGER NOT NULL,action_t_ieee754_class TEXT NOT NULL
);
CREATE TABLE en1993_joint(
 id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES en1993_document(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),logical_id TEXT NOT NULL,kind TEXT NOT NULL,member_id TEXT NOT NULL,bolt_class TEXT NOT NULL,bolt_diameter REAL,bolt_rows INTEGER NOT NULL CHECK(bolt_rows>=0 AND bolt_rows<=4294967295),bolts_per_row INTEGER NOT NULL CHECK(bolts_per_row>=0 AND bolts_per_row<=4294967295),pitch REAL,gauge REAL,end_distance REAL,edge_distance REAL,shear_planes INTEGER NOT NULL CHECK(shear_planes>=0 AND shear_planes<=4294967295),plate_thickness REAL,plate_fu REAL,weld_throat REAL,weld_length REAL,weld_fu REAL,weld_grade TEXT NOT NULL,category TEXT NOT NULL,friction_mu REAL,preload_force REAL,slip_factor_ks REAL,friction_surfaces INTEGER NOT NULL CHECK(friction_surfaces>=0 AND friction_surfaces<=4294967295),
 bolt_diameter_ieee754_bits INTEGER NOT NULL,bolt_diameter_ieee754_class TEXT NOT NULL,pitch_ieee754_bits INTEGER NOT NULL,pitch_ieee754_class TEXT NOT NULL,gauge_ieee754_bits INTEGER NOT NULL,gauge_ieee754_class TEXT NOT NULL,end_distance_ieee754_bits INTEGER NOT NULL,end_distance_ieee754_class TEXT NOT NULL,edge_distance_ieee754_bits INTEGER NOT NULL,edge_distance_ieee754_class TEXT NOT NULL,plate_thickness_ieee754_bits INTEGER NOT NULL,plate_thickness_ieee754_class TEXT NOT NULL,plate_fu_ieee754_bits INTEGER NOT NULL,plate_fu_ieee754_class TEXT NOT NULL,weld_throat_ieee754_bits INTEGER NOT NULL,weld_throat_ieee754_class TEXT NOT NULL,weld_length_ieee754_bits INTEGER NOT NULL,weld_length_ieee754_class TEXT NOT NULL,weld_fu_ieee754_bits INTEGER NOT NULL,weld_fu_ieee754_class TEXT NOT NULL,friction_mu_ieee754_bits INTEGER NOT NULL,friction_mu_ieee754_class TEXT NOT NULL,preload_force_ieee754_bits INTEGER NOT NULL,preload_force_ieee754_class TEXT NOT NULL,slip_factor_ks_ieee754_bits INTEGER NOT NULL,slip_factor_ks_ieee754_class TEXT NOT NULL
);
CREATE TABLE en1993_joint_action(
 id INTEGER PRIMARY KEY,joint_id INTEGER NOT NULL REFERENCES en1993_joint(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),logical_id TEXT NOT NULL,load_case_id TEXT NOT NULL,shear REAL,tension REAL,
 shear_ieee754_bits INTEGER NOT NULL,shear_ieee754_class TEXT NOT NULL,tension_ieee754_bits INTEGER NOT NULL,tension_ieee754_class TEXT NOT NULL
);
CREATE TABLE en1993_fatigue_detail(id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES en1993_document(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),logical_id TEXT NOT NULL,member_id TEXT NOT NULL,category INTEGER NOT NULL CHECK(category>=0 AND category<=255),method TEXT NOT NULL);
CREATE TABLE en1993_fatigue_band(
 id INTEGER PRIMARY KEY,detail_id INTEGER NOT NULL REFERENCES en1993_fatigue_detail(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),logical_id TEXT NOT NULL,delta_sigma REAL,cycles REAL,
 delta_sigma_ieee754_bits INTEGER NOT NULL,delta_sigma_ieee754_class TEXT NOT NULL,cycles_ieee754_bits INTEGER NOT NULL,cycles_ieee754_class TEXT NOT NULL
);
CREATE TABLE en1993_fire_exposure(
 id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES en1993_document(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),logical_id TEXT NOT NULL,member_id TEXT NOT NULL,rating TEXT NOT NULL,protection_thickness REAL,section_factor REAL,mu0 REAL,design_temperature REAL,protection_conductivity REAL,protection_density REAL,protection_specific_heat REAL,
 protection_thickness_ieee754_bits INTEGER NOT NULL,protection_thickness_ieee754_class TEXT NOT NULL,section_factor_ieee754_bits INTEGER NOT NULL,section_factor_ieee754_class TEXT NOT NULL,mu0_ieee754_bits INTEGER NOT NULL,mu0_ieee754_class TEXT NOT NULL,design_temperature_ieee754_bits INTEGER NOT NULL,design_temperature_ieee754_class TEXT NOT NULL,protection_conductivity_ieee754_bits INTEGER NOT NULL,protection_conductivity_ieee754_class TEXT NOT NULL,protection_density_ieee754_bits INTEGER NOT NULL,protection_density_ieee754_class TEXT NOT NULL,protection_specific_heat_ieee754_bits INTEGER NOT NULL,protection_specific_heat_ieee754_class TEXT NOT NULL
);
CREATE TABLE en1993_cold_formed_member(
 id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES en1993_document(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),logical_id TEXT NOT NULL,b_bar REAL,thickness REAL,k_sigma REAL,psi REAL,fy REAL,gross_resistance REAL,
 b_bar_ieee754_bits INTEGER NOT NULL,b_bar_ieee754_class TEXT NOT NULL,thickness_ieee754_bits INTEGER NOT NULL,thickness_ieee754_class TEXT NOT NULL,k_sigma_ieee754_bits INTEGER NOT NULL,k_sigma_ieee754_class TEXT NOT NULL,psi_ieee754_bits INTEGER NOT NULL,psi_ieee754_class TEXT NOT NULL,fy_ieee754_bits INTEGER NOT NULL,fy_ieee754_class TEXT NOT NULL,gross_resistance_ieee754_bits INTEGER NOT NULL,gross_resistance_ieee754_class TEXT NOT NULL
);
CREATE TABLE en1993_cold_formed_action(id INTEGER PRIMARY KEY,member_id INTEGER NOT NULL REFERENCES en1993_cold_formed_member(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),logical_id TEXT NOT NULL,load_case_id TEXT NOT NULL,force REAL,force_ieee754_bits INTEGER NOT NULL,force_ieee754_class TEXT NOT NULL);
CREATE TABLE en1993_plated_panel(
 id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES en1993_document(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),logical_id TEXT NOT NULL,a REAL,b REAL,thickness REAL,fy REAL,k_sigma REAL,
 a_ieee754_bits INTEGER NOT NULL,a_ieee754_class TEXT NOT NULL,b_ieee754_bits INTEGER NOT NULL,b_ieee754_class TEXT NOT NULL,thickness_ieee754_bits INTEGER NOT NULL,thickness_ieee754_class TEXT NOT NULL,fy_ieee754_bits INTEGER NOT NULL,fy_ieee754_class TEXT NOT NULL,k_sigma_ieee754_bits INTEGER NOT NULL,k_sigma_ieee754_class TEXT NOT NULL
);
CREATE TABLE en1993_plated_action(id INTEGER PRIMARY KEY,panel_id INTEGER NOT NULL REFERENCES en1993_plated_panel(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),logical_id TEXT NOT NULL,load_case_id TEXT NOT NULL,force REAL,force_ieee754_bits INTEGER NOT NULL,force_ieee754_class TEXT NOT NULL);
CREATE TABLE en1993_silo_shell(
 id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES en1993_document(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),logical_id TEXT NOT NULL,thickness REAL,radius REAL,depth REAL,k REAL,gamma REAL,fy REAL,
 thickness_ieee754_bits INTEGER NOT NULL,thickness_ieee754_class TEXT NOT NULL,radius_ieee754_bits INTEGER NOT NULL,radius_ieee754_class TEXT NOT NULL,depth_ieee754_bits INTEGER NOT NULL,depth_ieee754_class TEXT NOT NULL,k_ieee754_bits INTEGER NOT NULL,k_ieee754_class TEXT NOT NULL,gamma_ieee754_bits INTEGER NOT NULL,gamma_ieee754_class TEXT NOT NULL,fy_ieee754_bits INTEGER NOT NULL,fy_ieee754_class TEXT NOT NULL
);
CREATE TABLE en1993_tension_component(
 id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES en1993_document(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),logical_id TEXT NOT NULL,f_uk REAL,f_k REAL,
 f_uk_ieee754_bits INTEGER NOT NULL,f_uk_ieee754_class TEXT NOT NULL,f_k_ieee754_bits INTEGER NOT NULL,f_k_ieee754_class TEXT NOT NULL
);
CREATE TABLE en1993_tension_action(id INTEGER PRIMARY KEY,component_id INTEGER NOT NULL REFERENCES en1993_tension_component(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),logical_id TEXT NOT NULL,load_case_id TEXT NOT NULL,force REAL,force_ieee754_bits INTEGER NOT NULL,force_ieee754_class TEXT NOT NULL);
CREATE TABLE en1993_bridge_fatigue(
 id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES en1993_document(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),logical_id TEXT NOT NULL,member_id TEXT NOT NULL,lambda REAL,phi2 REAL,delta_sigma_p REAL,category INTEGER NOT NULL CHECK(category>=0 AND category<=255),method TEXT NOT NULL,
 lambda_ieee754_bits INTEGER NOT NULL,lambda_ieee754_class TEXT NOT NULL,phi2_ieee754_bits INTEGER NOT NULL,phi2_ieee754_class TEXT NOT NULL,delta_sigma_p_ieee754_bits INTEGER NOT NULL,delta_sigma_p_ieee754_class TEXT NOT NULL
);
CREATE TABLE en1993_tower_leg(
 id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES en1993_document(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),logical_id TEXT NOT NULL,member_id TEXT NOT NULL,force_coefficient REAL,dynamic_factor REAL,
 force_coefficient_ieee754_bits INTEGER NOT NULL,force_coefficient_ieee754_class TEXT NOT NULL,dynamic_factor_ieee754_bits INTEGER NOT NULL,dynamic_factor_ieee754_class TEXT NOT NULL
);
CREATE TABLE en1993_tower_action(id INTEGER PRIMARY KEY,leg_id INTEGER NOT NULL REFERENCES en1993_tower_leg(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),logical_id TEXT NOT NULL,load_case_id TEXT NOT NULL,force REAL,force_ieee754_bits INTEGER NOT NULL,force_ieee754_class TEXT NOT NULL);
CREATE TABLE en1993_pile(
 id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES en1993_document(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),logical_id TEXT NOT NULL,section_id TEXT NOT NULL,material_id TEXT NOT NULL,driving_stress REAL,embedded_length REAL,shaft_perimeter REAL,
 driving_stress_ieee754_bits INTEGER NOT NULL,driving_stress_ieee754_class TEXT NOT NULL,embedded_length_ieee754_bits INTEGER NOT NULL,embedded_length_ieee754_class TEXT NOT NULL,shaft_perimeter_ieee754_bits INTEGER NOT NULL,shaft_perimeter_ieee754_class TEXT NOT NULL
);
CREATE TABLE en1993_pile_action(id INTEGER PRIMARY KEY,pile_id INTEGER NOT NULL REFERENCES en1993_pile(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),logical_id TEXT NOT NULL,load_case_id TEXT NOT NULL,force REAL,force_ieee754_bits INTEGER NOT NULL,force_ieee754_class TEXT NOT NULL);
CREATE TABLE en1993_crane_runway(
 id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES en1993_document(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),logical_id TEXT NOT NULL,member_id TEXT NOT NULL,wheel_contact_length REAL,dispersion REAL,web_thickness REAL,fy REAL,phi REAL,
 wheel_contact_length_ieee754_bits INTEGER NOT NULL,wheel_contact_length_ieee754_class TEXT NOT NULL,dispersion_ieee754_bits INTEGER NOT NULL,dispersion_ieee754_class TEXT NOT NULL,web_thickness_ieee754_bits INTEGER NOT NULL,web_thickness_ieee754_class TEXT NOT NULL,fy_ieee754_bits INTEGER NOT NULL,fy_ieee754_class TEXT NOT NULL,phi_ieee754_bits INTEGER NOT NULL,phi_ieee754_class TEXT NOT NULL
);
CREATE TABLE en1993_crane_action(id INTEGER PRIMARY KEY,runway_id INTEGER NOT NULL REFERENCES en1993_crane_runway(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),logical_id TEXT NOT NULL,load_case_id TEXT NOT NULL,force REAL,force_ieee754_bits INTEGER NOT NULL,force_ieee754_class TEXT NOT NULL);
